with fixes as (select * from jsonb_to_recordset('[{"n": 2, "old": "C", "answer": "E", "explanation": "Split 2020 into 2000 + 20. Half of 2000 is 1000 and half of 20 is 10. Add them: half of 2020 is 1010, option E.", "skill": "DIG-01"}, {"n": 3, "old": "E", "answer": "B", "explanation": "The perimeter is the sum of all three side lengths, including the sloping sides: 11 + 7 + 16 = 34 m, option B.", "skill": "GEO-01"}, {"n": 4, "old": "B", "answer": "D", "explanation": "Compare the fractions as decimals: 1/2 = 0.5, 1/4 = 0.25, 1/3 \u2248 0.333, 3/4 = 0.75, and 6/10 = 0.6. The largest is three-quarters, option D.", "skill": "FRAC-01"}, {"n": 5, "old": "D", "answer": "A", "explanation": "Start at the zero on the left, along ray XP. Read the scale increasing toward ray XQ: it reaches 45\u00b0. The angle drawn is acute, so 135\u00b0 or 145\u00b0 cannot describe it. Choose 45\u00b0, option A; using the other protractor scale is the trap.", "skill": "GEO-03"}]'::jsonb) as x(n int,old text,answer text,explanation text,skill text)) update public.exam_questions q set answer=to_jsonb(f.answer),explanation=f.explanation,category=f.skill,metadata=coalesce(q.metadata,'{}'::jsonb)||jsonb_build_object('skill_id',f.skill,'answer_erratum',jsonb_build_object('previous_answer',f.old,'corrected_answer',f.answer,'reason','Independently solved from the supplied 2020 question image; original imported key was incorrect','corrected_on','2026-11-12')) from fixes f where q.exam_id='amc-up-2020' and q.question_number=f.n and q.answer=to_jsonb(f.old) returning q.question_number,q.answer;